<?php require 'config.php'; require_login(); $uid=$_SESSION['uid']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='save') { $title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$due=$_POST['due_date']??'';$subject=(int)($_POST['subject_id']??0);$validDate=DateTimeImmutable::createFromFormat('!Y-m-d',$due);$validSubject=true;
 if($subject){$st=$pdo->prepare('SELECT 1 FROM subjects WHERE id=? AND user_id=?');$st->execute([$subject,$uid]);$validSubject=(bool)$st->fetchColumn();}
 if($title==='' || mb_strlen($title)>200 || !$validDate || $validDate->format('Y-m-d')!==$due || !$validSubject) $error='Тақырыпты, күнді және пәнді дұрыс толтырыңыз.';
 else if($id){$st=$pdo->prepare('UPDATE tasks SET title=?,description=?,due_date=?,subject_id=? WHERE id=? AND user_id=?');$st->execute([$title,$desc,$due,$subject?:null,$id,$uid]);redirect();}
 else {$st=$pdo->prepare('INSERT INTO tasks(user_id,title,description,due_date,subject_id) VALUES(?,?,?,?,?)');$st->execute([$uid,$title,$desc,$due,$subject?:null]);redirect();} }
 elseif($action==='delete'){$st=$pdo->prepare('DELETE FROM tasks WHERE id=? AND user_id=?');$st->execute([$id,$uid]);redirect();}
 elseif($action==='toggle'){$st=$pdo->prepare("UPDATE tasks SET status=IF(status='pending','done','pending') WHERE id=? AND user_id=?");$st->execute([$id,$uid]);redirect();}
}
$st=$pdo->prepare('SELECT * FROM subjects WHERE user_id=? ORDER BY name');$st->execute([$uid]);$subjects=$st->fetchAll();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM tasks WHERE id=? AND user_id=?');$st->execute([(int)$_GET['edit'],$uid]);$edit=$st->fetch()?:null;}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT t.*,s.name subject_name FROM tasks t LEFT JOIN subjects s ON t.subject_id=s.id WHERE t.user_id=?';$args=[$uid];if($q!==''){$sql.=' AND (t.title LIKE ? OR s.name LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if(in_array($status,['pending','done'],true)){$sql.=' AND t.status=?';$args[]=$status;}$sql.=' ORDER BY t.due_date ASC,t.id DESC';$st=$pdo->prepare($sql);$st->execute($args);$tasks=$st->fetchAll();require 'header.php'; ?>
<div class="hero"><h1>Менің оқу жоспарым</h1><p>Сабақ пен үй тапсырмаларын бір жерде басқар.</p></div><section class="panel"><h2><?=$edit?'Тапсырманы өзгерту':'Жаңа тапсырма'?></h2><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form method="post" class="form-grid"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Тапсырма атауы<input name="title" maxlength="200" required value="<?=e($edit['title']??'')?>"></label><label>Орындалу күні<input type="date" name="due_date" required value="<?=e($edit['due_date']??date('Y-m-d'))?>"></label><label>Пән<select name="subject_id"><option value="0">Пән таңдалмаған</option><?php foreach($subjects as $s): ?><option value="<?=$s['id']?>" <?=($edit['subject_id']??'')==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach; ?></select></label><label>Сипаттама<input name="description" value="<?=e($edit['description']??'')?>"></label><button><?=$edit?'Сақтау':'Қосу'?></button></form></section>
<section class="panel"><h2>Тапсырмалар</h2><form method="get" class="inline"><input name="q" placeholder="Тапсырма немесе пән іздеу" value="<?=e($q)?>"><select name="status"><option value="">Барлығы</option><option value="pending" <?=$status==='pending'?'selected':''?>>Орындалмаған</option><option value="done" <?=$status==='done'?'selected':''?>>Орындалған</option></select><button>Іздеу</button></form><?php foreach($tasks as $t): ?><article class="task"><div><strong><?=e($t['title'])?></strong><p><?=e($t['subject_name']??'Пәнсіз')?> · <?=e($t['due_date'])?> · <span class="<?= $t['status']==='done'?'success':'pending' ?>"><?=$t['status']==='done'?'Орындалды':'Күтілуде'?></span></p><?php if($t['description']): ?><p><?=e($t['description'])?></p><?php endif; ?></div><div class="actions"><form method="post"><?=csrf()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="secondary">✓</button></form><a class="btn secondary" href="?edit=<?=$t['id']?>">Өзгерту</a><form method="post" onsubmit="return confirm('Өшіру керек пе?')"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="danger">Өшіру</button></form></div></article><?php endforeach; ?><?php if(!$tasks): ?><p>Тапсырмалар табылмады.</p><?php endif; ?></section><?php require 'footer.php'; ?>
